fast_pseudocode:
# @triton.autotune wired to lambda grid — autotune controls tile shape
@triton.autotune(configs=[...15 configs with XBLOCK/YBLOCK variants...], key=['ynumel','xnumel'])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

def kernel_function(*inputs):
    ynumel = 30
    xnumel = 50176
    grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']), triton.cdiv(ynumel, meta['YBLOCK']))  # reads autotuned config
    kernel[grid](in_ptr, out_ptr, ynumel, xnumel)
